	\caption{Banded Matrix Decomposition}
	\begin{algorithmic}[1]
		\Statex {\bf Input:} $\Sigma \in M_n(\mathbb R)$ - a real Positive Definite matrix, ${D} \leq n-1$ - band width.
		\Statex {\bf Output:} Two matrices $R+\hat\Gamma={\Sigma}^{-1}$ such that $R^{-1} \in {\mathcal{S}}_{{D}}, \hat\Gamma \in {\mathcal{T}}_{{D}}$.
		\State Compute the inverse ${\Lambda}=\Sigma^{-1}$ and set $R_{ij} = {\Lambda}_{ij}, \forall |i-j|\leq {D}$.
		\For{$m={D}+1$ to $n-1$} 
		\For{$i=1$ to $n-m$} 
		\State Set $$R_{i+m i}, R_{i i+m} = \frac{\sum\limits_{j=1}^{{D}} (-1)^{j+{D}} R_{i i+j} R_{[i+1:i+{D}]^{i+j \to i+m}}^{[i+1:i+{D}]}}{R_{[i+1:i+{D}]}^{[i+1:i+{D}]}}.$$
		\EndFor	 
		\EndFor	 
		\State Set $\hat\Gamma = {\Lambda}-R$.
		\State Output the matrices $R, \hat\Gamma$. 
\end{algorithmic}
\label{alg:band_decomposition}

